SELECT CASE WHEN monthly_fee >= 198 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_tier, COUNT_IF(status = 'CANCELLED') AS cancelled_events, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee_2, SORT_ARRAY(COLLECT_SET(status)) AS status_list, SIZE(COLLECT_SET(plan)) AS num_plans FROM subscriptions GROUP BY CASE WHEN monthly_fee >= 198 THEN 'HIGH' ELSE 'LOW' END ORDER BY num_plans DESC
